INSERT INTO kairo.questions (id, subject, topic, subtopic, learning_objective, concepts_tested, prerequisite_concepts, difficulty_rating, cognitive_level, estimated_solving_time_sec, reading_load, calculation_load, distractors, skills_assessed, source, year, exam_body, related_question_ids, stem, options, correct_option, explanation, lifecycle_state, empirical_stats) VALUES
('mathematics_0076', 'Mathematics', 'Permutations and combinations', 'Combinations (Choosing r from n)', NULL, '[{"weight": 1, "conceptId": "cmb4nk"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "This is C(12,4) computed incorrectly (an arithmetic slip in the numerator/denominator).", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "496 is one more than the correct value, from an off-by-one slip in the combination calculation.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "498 overshoots the correct value, from a computational slip while multiplying/dividing the combination formula.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'Find the number of ways of selecting 8 subjects from 12 subjects for an examination', '[{"label": "A", "text": "490", "isCorrect": false}, {"label": "B", "text": "495", "isCorrect": true}, {"label": "C", "text": "496", "isCorrect": false}, {"label": "D", "text": "498", "isCorrect": false}]'::jsonb, 'B', 'Choosing 8 subjects from 12 is C(12,8) = C(12,4) = (12x11x10x9)/(4x3x2x1) = 495.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0077', 'Mathematics', 'Differentiation', 'Product Rule Differentiation (Expression Form)', NULL, '[{"weight": 1, "conceptId": "prdrle"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "This drops the (2x+5)^2 term entirely, keeping only the derivative of the first factor times the second.", "misconceptionId": "formula_recall_error"}, {"option": "B", "explanation": "This mis-expands 4(x-4)+(2x+5) as 4x-3 instead of correctly combining to 6x-11.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "This applies the derivative to only one factor and drops the leading 2, losing a factor from the chain rule.", "misconceptionId": "formula_recall_error"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'Differentiate (2x+5)^2 (x-4) with respect to x.', '[{"label": "A", "text": "4(2x+5)(x-4)", "isCorrect": false}, {"label": "B", "text": "4(2x+5)(4x-3)", "isCorrect": false}, {"label": "C", "text": "(2x+5)(2x-13)", "isCorrect": false}, {"label": "D", "text": "(2x+5)(6x-11)", "isCorrect": true}]'::jsonb, 'D', 'Using the product rule: d/dx[(2x+5)^2(x-4)] = 2(2x+5)(2)(x-4) + (2x+5)^2(1) = (2x+5)[4(x-4)+(2x+5)] = (2x+5)(6x-11).', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0078', 'Mathematics', 'Applications of integration', 'Area Between Two Curves', NULL, '[{"weight": 1, "conceptId": "abtwcv"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "20 1/3 is roughly double the correct area, from a sign or bounds slip in the definite integral.", "misconceptionId": "sign_error"}, {"option": "B", "explanation": "20 2/3 doubles the correct area, likely from forgetting to divide the final antiderivative evaluation by 2 or a bounds mix-up.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "10 1/3 is close to the correct value but comes from an arithmetic slip while evaluating the antiderivative at the limits.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'Find the area bounded by the curves y = 4 - x2 and y = 2x + 1', '[{"label": "A", "text": "20(1/3) sq. units", "isCorrect": false}, {"label": "B", "text": "20(2/3) sq. units", "isCorrect": false}, {"label": "C", "text": "10(2/3) sq. units", "isCorrect": true}, {"label": "D", "text": "10(1/3) sq. units", "isCorrect": false}]'::jsonb, 'C', 'The curves meet where 4-x^2=2x+1, i.e. x^2+2x-3=0, so x=-3 or x=1. Integrating (4-x^2)-(2x+1)=3-2x-x^2 from -3 to 1 gives [3x-x^2-x^3/3] evaluated at 1 minus at -3 = 5/3-(-9) = 32/3 = 10 2/3 sq. units.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0079', 'Mathematics', 'Triangles', 'Isosceles Triangle Angle Chasing (Exterior Angle Theorem)', NULL, '[{"weight": 1, "conceptId": "isoexa"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "50 is the value of <TQR (the exterior angle at Q), not the final angle <RST asked for.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "25 is the given base angle <QPT, mistakenly carried through as the final answer.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "45 results from an arithmetic slip while summing the angles of triangle QRS to 180 degrees.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'In the figure PQR a straight line segment, PQ = QT. Triangle PQT is an isosceles triangle, < SRQ is 75º and < QPT IS 25º. Calculate the value of < RST', '[{"label": "A", "text": "50", "isCorrect": false}, {"label": "B", "text": "25", "isCorrect": false}, {"label": "C", "text": "55", "isCorrect": true}, {"label": "D", "text": "45", "isCorrect": false}]'::jsonb, 'C', 'Since PQ=QT, triangle PQT is isosceles with base angles <QPT=<QTP=25 degrees, so <PQT=130 degrees. As PQR is a straight line, <TQR=180-130=50 degrees (exterior angle of the triangle). In triangle QRS, <RQS=50 and <SRQ=75, so <RST=180-50-75=55 degrees.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0080', 'Mathematics', 'Applications of differentiation', 'Optimization (Maximum Area with Fixed Perimeter)', NULL, '[{"weight": 1, "conceptId": "optmxa"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "A square of side p would need a perimeter of 4p, not the fixed perimeter p given.", "misconceptionId": "formula_recall_error"}, {"option": "B", "explanation": "A square of side 2p is far larger than the fixed perimeter p allows.", "misconceptionId": "formula_recall_error"}, {"option": "C", "explanation": "A square of side p/2 corresponds to a perimeter of 2p, not the given fixed perimeter p.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'Find the dimensions of a rectangle of greatest area which has a fixed perimeter p.', '[{"label": "A", "text": "square of sides p", "isCorrect": false}, {"label": "B", "text": "square of sides 2p", "isCorrect": false}, {"label": "C", "text": "square of sides (p/2)", "isCorrect": false}, {"label": "D", "text": "square of sides (p/4)", "isCorrect": true}]'::jsonb, 'D', 'For a rectangle with fixed perimeter p, area A=l(p/2-l) is maximized (dA/dl=0) at l=p/4, giving w=p/4 too -- i.e. a square of side p/4.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0081', 'Mathematics', 'Matrices and determinants', 'Matrix Polynomial Expressions', NULL, '[{"weight": 1, "conceptId": "mtxply"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "This results from computing K+I only and mis-combining entries, omitting K^2 correctly.", "misconceptionId": "formula_recall_error"}, {"option": "B", "explanation": "This comes from an arithmetic slip while multiplying K by itself to get K^2.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "This has a sign/arithmetic slip in one entry while adding K^2, K and I together.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'Given the matrix K = [[2,1],[3,4]], the matrix K^2 + K + I, where I is the 2 x 2 identity matrix, is', '[{"label": "A", "text": "[[6,3],[3,20]]", "isCorrect": false}, {"label": "B", "text": "[[9,8],[22,23]]", "isCorrect": false}, {"label": "C", "text": "[[10,7],[21,24]]", "isCorrect": true}, {"label": "D", "text": "[[7,2],[12,21]]", "isCorrect": false}]'::jsonb, 'C', 'K^2 = [[7,6],[18,19]]. Adding K gives [[9,7],[21,23]], and adding I gives [[10,7],[21,24]].', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0082', 'Mathematics', 'Factorization', 'Factorization by Grouping (Difference of Squares Combined)', NULL, '[{"weight": 1, "conceptId": "facdsq"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "This treats the whole expression as a plain difference of squares of (2x-3y) and 5, ignoring the +20x term needed to complete the square (2x+5)^2.", "misconceptionId": "overgeneralized_rule"}, {"option": "B", "explanation": "This is just the difference of squares of 2x and 3y, ignoring the +20x+25 terms entirely.", "misconceptionId": "missing_prerequisite"}, {"option": "D", "explanation": "This factorization does not multiply back to the original expression -- an invalid grouping of terms.", "misconceptionId": "confused_similar_concepts"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'Factorize 4x 2 - 9y 2 + 20x + 25', '[{"label": "A", "text": "(2x -3y + 5)(2x - 3y - 5)", "isCorrect": false}, {"label": "B", "text": "(2x - 3y)(2x + 3y)", "isCorrect": false}, {"label": "C", "text": "(2x - 3y +5)(2x + 3y + 5)", "isCorrect": true}, {"label": "D", "text": "(2x + 5)(2x - 9y +5)", "isCorrect": false}]'::jsonb, 'C', '4x^2+20x+25-9y^2 = (2x+5)^2-(3y)^2, a difference of two squares, which factorizes as (2x+5-3y)(2x+5+3y) = (2x-3y+5)(2x+3y+5).', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0083', 'Mathematics', 'Indices', 'Laws of Indices', NULL, '[{"weight": 1, "conceptId": "mathind1"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "4a is the cube root itself, before taking the inverse (power -1).", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "1/8a results from mistakenly cube-rooting 64 as 8 rather than 4.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "8a mistakenly treats the cube root of 64 as 8 instead of 4.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'Simplify (cube root of 64a^3)^(-1)', '[{"label": "A", "text": "4a", "isCorrect": false}, {"label": "B", "text": "1/8a", "isCorrect": false}, {"label": "C", "text": "8a", "isCorrect": false}, {"label": "D", "text": "1/4a", "isCorrect": true}]'::jsonb, 'D', 'The cube root of 64a^3 is 4a (since 4^3=64). Its inverse (power -1) is 1/(4a).', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0084', 'Mathematics', 'Binary operations', 'Identity and Inverse Elements', NULL, '[{"weight": 1, "conceptId": "cuzren"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "4 comes from adding instead of solving for the inverse using the identity equation.", "misconceptionId": "formula_recall_error"}, {"option": "B", "explanation": "Zero would be the inverse if the identity element were 3, not -1.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "-2 results from a sign slip while solving 2+x+1=-1 for x.", "misconceptionId": "sign_error"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'An operation * is defined on the set of real numbers by a*b = a + b + 1. If the identity elements is -1, find the inverse of the element 2 under *.', '[{"label": "A", "text": "4", "isCorrect": false}, {"label": "B", "text": "zero", "isCorrect": false}, {"label": "C", "text": "-2", "isCorrect": false}, {"label": "D", "text": "-4", "isCorrect": true}]'::jsonb, 'D', 'For a*b=a+b+1 with identity e=-1, the inverse of 2 satisfies 2*x=-1, i.e. 2+x+1=-1, so x=-4.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0085', 'Mathematics', 'Percentages', 'Simple Interest', NULL, '[{"weight": 1, "conceptId": "46gg3b"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "N4,900 results from an arithmetic slip while dividing 5500 by 1.1.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "N4,700 results from a larger arithmetic slip in the division.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "N4,800 results from an arithmetic slip while solving for the principal.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'Find the principal which amounts to N5,500 at a simple interest in 5 years at 2% per annum.', '[{"label": "A", "text": "N4,900", "isCorrect": false}, {"label": "B", "text": "N5,000", "isCorrect": true}, {"label": "C", "text": "N4,700", "isCorrect": false}, {"label": "D", "text": "N4,800", "isCorrect": false}]'::jsonb, 'B', 'Using A=P(1+rt): 5500=P(1+0.02x5)=1.1P, so P=5500/1.1=N5,000.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0086', 'Mathematics', 'Percentages', 'Profit and Loss', NULL, '[{"weight": 1, "conceptId": "r9oudo"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "60% results from computing the gain as a percentage of the purchase price alone (N250,000), ignoring the refurbishing cost.", "misconceptionId": "formula_recall_error"}, {"option": "B", "explanation": "32% comes from computing gain as a percentage of the selling price instead of the total cost.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "20% results from an arithmetic slip while dividing the gain by the total cost.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'A car dealer bought a second-hand car for N250,000 and spent N70,000 refurbishing it. He then sold the car for N400,000. What is the percentage gain?', '[{"label": "A", "text": "60%", "isCorrect": false}, {"label": "B", "text": "32%", "isCorrect": false}, {"label": "C", "text": "25%", "isCorrect": true}, {"label": "D", "text": "20%", "isCorrect": false}]'::jsonb, 'C', 'Total cost = N250,000+N70,000=N320,000. Gain = N400,000-N320,000=N80,000. Percentage gain = 80,000/320,000x100 = 25%.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0087', 'Mathematics', 'Surds', 'Algebraic Manipulation of Surd Expressions', NULL, '[{"weight": 1, "conceptId": "surdmn"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "2(2+sqrt(2)) results from expanding p^2 and q^2 separately with sign errors rather than using the difference-of-squares shortcut.", "misconceptionId": "sign_error"}, {"option": "B", "explanation": "-2(2+sqrt(2)) carries the same expansion error as option A but with an extra sign flip.", "misconceptionId": "sign_error"}, {"option": "C", "explanation": "2sqrt(2) is missing the negative sign from pq=-1, an overlooked sign error.", "misconceptionId": "sign_error"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'Given that p = 1 + sqrt(2) and q = 1 - sqrt(2), evaluate (p^2 - q^2)/(2pq).', '[{"label": "A", "text": "2(2+√2)", "isCorrect": false}, {"label": "B", "text": "-2(2+√2)", "isCorrect": false}, {"label": "C", "text": "2√2", "isCorrect": false}, {"label": "D", "text": "-2√2", "isCorrect": true}]'::jsonb, 'D', 'p+q=2, p-q=2sqrt(2), so p^2-q^2=(p+q)(p-q)=4sqrt(2). Also pq=(1+sqrt(2))(1-sqrt(2))=1-2=-1, so 2pq=-2. Thus (p^2-q^2)/(2pq)=4sqrt(2)/(-2)=-2sqrt(2).', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0088', 'Mathematics', 'Trigonometric functions', 'Bearings (Finding Bearing Between Two Points)', NULL, '[{"weight": 1, "conceptId": "bearfp"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "040 results from a slip in combining the base angle with the bearing of N from Q.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "280 is the back-bearing-like value on the wrong side, from confusing the direction of measurement.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "320 results from measuring the bearing of P from Q in the wrong rotational sense.", "misconceptionId": "confused_similar_concepts"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'The bearings of P and Q from a common point N are 020° and 300° respectively. If P and Q are also equidistant from N, find the bearing of P from Q.', '[{"label": "A", "text": "040°", "isCorrect": false}, {"label": "B", "text": "070°", "isCorrect": true}, {"label": "C", "text": "280°", "isCorrect": false}, {"label": "D", "text": "320°", "isCorrect": false}]'::jsonb, 'B', 'The angle PNQ between the bearings 020 and 300 is 80 degrees (going clockwise from 300 to 020 the short way). Since NP=NQ, triangle NPQ is isosceles with base angles (180-80)/2=50 degrees. Working out the bearing of P from Q using these angles and the given directions gives a bearing of 070 degrees.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0089', 'Mathematics', 'Circles', 'Radius from Diameter Endpoints (Distance Formula)', NULL, '[{"weight": 1, "conceptId": "raddfe"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "B", "explanation": "13.0 units is the full diameter, not the radius -- forgetting to halve the distance PQ.", "misconceptionId": "formula_recall_error"}, {"option": "C", "explanation": "3.5 units results from an arithmetic slip while computing the distance PQ.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "7.0 units results from a slip while taking the square root of 169 or halving it.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'P(-6, 1) and Q(6, 6) are the two ends of the diameter of a given circle. Calculate the radius.', '[{"label": "A", "text": "6.5 units", "isCorrect": true}, {"label": "B", "text": "13.0 units", "isCorrect": false}, {"label": "C", "text": "3.5 units", "isCorrect": false}, {"label": "D", "text": "7.0 units", "isCorrect": false}]'::jsonb, 'A', 'Using the distance formula, PQ = sqrt((6-(-6))^2+(6-1)^2) = sqrt(144+25) = sqrt(169) = 13. Since PQ is the diameter, the radius is 13/2 = 6.5 units.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0090', 'Mathematics', 'Loci', 'Locus of a Point Moving Parallel to a Line', NULL, '[{"weight": 1, "conceptId": "epzhpc"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "B", "explanation": "y=k +/- 4 incorrectly swaps the roles of the fixed line''s position and the constant distance.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "y=4+k only gives one of the two parallel lines forming the locus, missing the branch below the line.", "misconceptionId": "overgeneralized_rule"}, {"option": "D", "explanation": "y=k-4 incorrectly treats k as the base position rather than the distance from y=4.", "misconceptionId": "confused_similar_concepts"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'Find the locus of a point which moves such that its distance from the line y = 4 is a constant, k.', '[{"label": "A", "text": "y = 4 ± k", "isCorrect": true}, {"label": "B", "text": "y = k ± 4", "isCorrect": false}, {"label": "C", "text": "y = 4 + k", "isCorrect": false}, {"label": "D", "text": "y = k - 4", "isCorrect": false}]'::jsonb, 'A', 'A point at a constant perpendicular distance k from the horizontal line y=4 traces two lines parallel to it, k units above and below: y=4+k and y=4-k, i.e. y=4 +/- k.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0091', 'Mathematics', 'Fractions, decimals and approximations', 'Evaluating Decimal Expressions to Given Decimal Places', NULL, '[{"weight": 1, "conceptId": "decexp"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "B", "explanation": "0.385 is ten times too large, from a decimal point placement slip.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "0.033 results from an arithmetic slip in the division step.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "0.038 rounds the exact value 0.0385 down instead of up to 3 decimal places.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'Evaluate (0.14^2 x 0.275)/(7(0.02)) to 3 decimal places.', '[{"label": "A", "text": "0.039", "isCorrect": true}, {"label": "B", "text": "0.385", "isCorrect": false}, {"label": "C", "text": "0.033", "isCorrect": false}, {"label": "D", "text": "0.038", "isCorrect": false}]'::jsonb, 'A', '0.14^2=0.0196, times 0.275 gives 0.00539. The denominator is 7x0.02=0.14. Dividing: 0.00539/0.14=0.0385, which rounds to 0.039 to 3 decimal places.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0092', 'Mathematics', 'Measures of dispersion', 'Interquartile Range', NULL, '[{"weight": 1, "conceptId": "iqrang"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "1/2(Q3-Q1) is the semi-interquartile range (quartile deviation), not the interquartile range itself.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Q3-Q2 only spans the upper half of the middle 50% of data, not the full interquartile range.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "Q2-Q1 only spans the lower half of the middle 50% of data, not the full interquartile range.", "misconceptionId": "misunderstood_terminology"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'The graph shows the cumulative frequency of the distribution of masses of fertilizer for 48 workers in one institution. Which of the following gives the inter-quartile range?', '[{"label": "A", "text": "1/2(Q3 - Q1)", "isCorrect": false}, {"label": "B", "text": "Q3 - Q1", "isCorrect": true}, {"label": "C", "text": "Q3 - Q2", "isCorrect": false}, {"label": "D", "text": "Q2 - Q1", "isCorrect": false}]'::jsonb, 'B', 'The interquartile range is defined as the third quartile minus the first quartile: Q3 - Q1.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0093', 'Mathematics', 'Polynomials', 'Polynomial Division Using Substitution', NULL, '[{"weight": 1, "conceptId": "polydv"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "B", "explanation": "a^x+2 has the correct constant magnitude but the wrong sign, from a sign slip during the division.", "misconceptionId": "sign_error"}, {"option": "C", "explanation": "a^x-8 results from an arithmetic slip in one of the subtraction steps of the long division.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "a^x-6 results from an arithmetic slip in one of the subtraction steps of the long division.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'Divide: a^(3x) - 26a^(2x) + 156a^x - 216 by a^(2x) - 24a^x + 108.', '[{"label": "A", "text": "a^x - 2", "isCorrect": true}, {"label": "B", "text": "a^x + 2", "isCorrect": false}, {"label": "C", "text": "a^x - 8", "isCorrect": false}, {"label": "D", "text": "a^x - 6", "isCorrect": false}]'::jsonb, 'A', 'Substituting z=a^x turns the division into (z^3-26z^2+156z-216) / (z^2-24z+108). Dividing gives quotient z-2, i.e. a^x-2.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0094', 'Mathematics', 'Coordinate geometry', 'Equation of a Line (Gradient from Angle)', NULL, '[{"weight": 1, "conceptId": "linega"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "y=(x/10)+5 uses an incorrect value for tan(30) instead of 1/sqrt(3).", "misconceptionId": "formula_recall_error"}, {"option": "B", "explanation": "y=x+5 uses a gradient of 1 (as if the angle were 45 degrees) instead of tan(30).", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "sqrt(3)y=-x+5sqrt(3) has a sign error, giving a line sloping the opposite way.", "misconceptionId": "sign_error"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'A straight line makes an angle of 30° with the positive x-axis and cuts the y-axis at y = 5. Find the equation of the straight line.', '[{"label": "A", "text": "y = (x/10) + 5", "isCorrect": false}, {"label": "B", "text": "y = x + 5", "isCorrect": false}, {"label": "C", "text": "√3y = - x + 5√3", "isCorrect": false}, {"label": "D", "text": "√3y = x + 5√3", "isCorrect": true}]'::jsonb, 'D', 'Gradient = tan(30) = 1/sqrt(3). With y-intercept 5: y = x/sqrt(3) + 5. Multiplying through by sqrt(3): sqrt(3)y = x + 5sqrt(3).', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0095', 'Mathematics', 'Differentiation', 'Product Rule at a Point', NULL, '[{"weight": 1, "conceptId": "40mgg1"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "-pi/2 results from evaluating the wrong term or a sign slip in the product rule expansion.", "misconceptionId": "sign_error"}, {"option": "B", "explanation": "-1 results from a sign error when substituting x=pi/2 into the derivative.", "misconceptionId": "sign_error"}, {"option": "D", "explanation": "pi/2 mistakenly keeps the x*cos(x) term as if cos(pi/2) were 1 instead of 0.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'If y = x sinx, find dy/dx when x = π/2.', '[{"label": "A", "text": "-π/2", "isCorrect": false}, {"label": "B", "text": "-1", "isCorrect": false}, {"label": "C", "text": "1", "isCorrect": true}, {"label": "D", "text": "π/2", "isCorrect": false}]'::jsonb, 'C', 'dy/dx = sinx + x cosx (product rule). At x=pi/2: sin(pi/2)=1 and cos(pi/2)=0, so dy/dx = 1 + (pi/2)(0) = 1.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0096', 'Mathematics', 'Triangles', 'Isosceles Triangle from Equidistant Point (Sine Rule)', NULL, '[{"weight": 1, "conceptId": "isoeqp"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "A", "explanation": "4sqrt(3)cm is half the correct length, from a slip in applying the sine rule.", "misconceptionId": "arithmetic_slip"}, {"option": "B", "explanation": "8cm mistakenly assumes QR equals the given side PR rather than computing it via the sine rule.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "4cm results from halving PR instead of correctly applying the sine rule.", "misconceptionId": "formula_recall_error"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'A point P moves such that it is equidistant from Points Q and R. Find QR when PR = 8cm and angle PRQ = 30°', '[{"label": "A", "text": "4√3cm", "isCorrect": false}, {"label": "B", "text": "8cm", "isCorrect": false}, {"label": "C", "text": "8√3cm", "isCorrect": true}, {"label": "D", "text": "4cm", "isCorrect": false}]'::jsonb, 'C', 'Since P is equidistant from Q and R, PQ=PR=8cm, making triangle PQR isosceles with the base angles at Q and R equal: angle PRQ=angle PQR=30 degrees, so angle QPR=120 degrees. By the sine rule, QR/sin(P)=PR/sin(Q), giving QR=8xsin(120)/sin(30)=8xsqrt(3)=8sqrt(3)cm.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb),
('mathematics_0097', 'Mathematics', 'Coordinate geometry', 'Perpendicular Lines', NULL, '[{"weight": 1, "conceptId": "qip98q"}]'::jsonb, '{}', 2, 'application', 90, 'medium', 'moderate', '[{"option": "B", "explanation": "6 results from a sign or algebraic slip while solving the perpendicularity equation.", "misconceptionId": "sign_error"}, {"option": "C", "explanation": "3 results from an arithmetic slip while cross-multiplying the perpendicularity condition.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "0 results from mishandling the equation and losing the P term prematurely.", "misconceptionId": "arithmetic_slip"}]'::jsonb, '{}', 'jamb_past_question', 2001, 'JAMB', '{}', 'Find the value of P if the line joining (P, 4) and (6, -2) is perpendicular to the line joining (2, P) and (-1, 3).', '[{"label": "A", "text": "4", "isCorrect": true}, {"label": "B", "text": "6", "isCorrect": false}, {"label": "C", "text": "3", "isCorrect": false}, {"label": "D", "text": "0", "isCorrect": false}]'::jsonb, 'A', 'Gradient of the first line: (-2-4)/(6-P) = -6/(6-P). Gradient of the second: (3-P)/(-1-2) = (P-3)/3. Perpendicular lines satisfy m1 x m2 = -1, which solves to P=4.', 'live', '{"totalAttempts": 0, "correctCount": 0, "avgResponseTimeMs": 0, "distractorSelectionCounts": {}}'::jsonb);
